package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd
 */
public class MathUtils_gcd_TriageGen1Test {





    @Test
    public void testGcdWithZero() {
        // If one is zero, return the absolute value of the other
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(-5, MathUtils.gcd(-5, 0)); // Based on (Math.abs(u) + Math.abs(v)) logic in code
        // Wait, looking at the code: return (Math.abs(u) + Math.abs(v));
        // If u=-5, v=0 -> Math.abs(-5) + Math.abs(0) = 5.
        assertEquals(5, MathUtils.gcd(-5, 0));
        assertEquals(5, MathUtils.gcd(0, -5));
    }














}

