package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd
 */
public class MathUtils_gcd_TriageGen1Test {



















    @Test
    public void testGcdSpecificBranchLogic() {
        // B2/B3: u was odd, v may be even (t replaces v)
        // u = -3, v = -2. k=0. u is odd. t = v = -2.
        // Loop: t is even -> t = -1. t is odd. t < 0 -> v = -1.
        // t = (v-u)/2 = (-1 - (-3))/2 = 1.
        // Loop: t=1. t is odd. t > 0 -> u = -1.
        // t = (v-u)/2 = (-1 - (-1))/2 = 0. Loop ends.
        // result -u * 2^0 = 1 * 1 = 1.
        assertEquals(1, MathUtils.gcd(3, 2));

        // u even, v odd
        assertEquals(1, MathUtils.gcd(2, 3));
    }
}
